import requests
for q in ['LEUKINE','SARGRAMOSTIM','filgrastim']:
 u='https://dailymed.nlm.nih.gov/dailymed/services/v2/spls.json'
 r=requests.get(u,params={'drug_name':q},timeout=20)
 print('\nQUERY',q,'STATUS',r.status_code)
 try:
  for x in r.json().get('data',[])[:5]: print(x.get('title'),x.get('setid'))
 except Exception as e: print(r.text[:300])
